CREATE TABLE IF NOT EXISTS gis_evidence_conflicts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), candidate_match_id uuid NOT NULL, evidence_a_id uuid NOT NULL, evidence_b_id uuid NOT NULL, conflict_reason text NOT NULL, authority_a text, authority_b text, provenance_a boolean NOT NULL DEFAULT false, provenance_b boolean NOT NULL DEFAULT false, status text NOT NULL DEFAULT 'REQUIRES_REVIEW', resolution_note text, resolved_by text, resolved_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(candidate_match_id,evidence_a_id,evidence_b_id));
CREATE INDEX IF NOT EXISTS gis_evidence_conflicts_candidate_idx ON gis_evidence_conflicts(candidate_match_id,status);